Unified API Gateway.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Unified API Gateway container

Container_Boundary(unified_api_gateway, "Unified API Gateway") {
    Component(api_gateway, "API Gateway", "Kong/Envoy", "Handles rate-limiting, TLS 1.3 termination, and entry point routing for inbound traffic.")
    Component(lua_wasm_plugins, "Lua/Wasm Plugins", "Lua / Wasm", "Implements zero-trust token validation, JWT verification, and security checks.")
}

Rel(api_gateway, lua_wasm_plugins, "Evaluates inbound requests for zero-trust token validation and routing", "")

@enduml

EMR Microservice.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(emr_microservice, "EMR Microservice") {
    Component(EMR_API_Handler, "EMR API Handler", "Go / gRPC", "Handles incoming gRPC requests for electronic medical records from the Unified API Gateway.")
    Component(EMR_Domain_Service, "EMR Domain Service", "Go", "Contains business logic for managing electronic medical records and patient health information.")
    Component(EMR_Data_Access_Repository, "EMR Data Access Repository", "SQL / TLS", "Manages database operations and queries against the Cloud-Native Distributed SQL Database.")
}

System_Ext(Cloud_Native_Distributed_SQL_Database, "Cloud-Native Distributed SQL Database", "CockroachDB")

Rel(EMR_API_Handler, EMR_Domain_Service, "Delegates requests to", "")
Rel(EMR_Domain_Service, EMR_Data_Access_Repository, "Queries and updates records via", "")
Rel(EMR_Data_Access_Repository, Cloud_Native_Distributed_SQL_Database, "Executes SQL statements over TLS", "SQL / TLS")
@enduml

Async Claims Processing Worker.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(async_claims_processing_worker, "Async Claims Processing Worker") {
    Component(Claims_Consumer, "Claims Consumer", "Node.js / Kafka Consumer", "Consumes asynchronous claims processing jobs from the message broker.")
    Component(EDI_Formatter, "EDI Formatter", "TypeScript / EDI Parser", "Formats processed claims into secure EDI format for clearinghouse submission.")
    Component(Clearinghouse_Integration_Client, "Clearinghouse Integration Client", "HTTPS Client with Circuit Breakers", "Communicates securely with external insurance clearinghouses using circuit breakers.")
}

Rel(Claims_Consumer, EDI_Formatter, "Passes raw claim messages for formatting")
Rel(EDI_Formatter, Clearinghouse_Integration_Client, "Sends formatted EDI payloads")
@enduml

Cloud-Native Distributed SQL Database.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(cloud_native_distributed_sql_database, "Cloud-Native Distributed SQL Database") {
    Component(sql_layer, "SQL Layer", "CockroachDB SQL Engine", "Parses, optimizes, and executes SQL queries and provides PostgreSQL wire protocol compatibility.")
    Component(distributed_transaction_engine, "Distributed Transaction Engine", "CockroachDB Distributed Transaction Coordinator", "Coordinates distributed ACID transactions across multiple nodes and shards.")
    Component(storage_layer_raft_consensus_rocksdb, "Storage Layer (Raft Consensus & RocksDB)", "RocksDB & Raft Consensus", "Persists data using RocksDB storage engines and ensures replication and consensus via Raft.")
}

Rel(sql_layer, distributed_transaction_engine, "Routes queries for transaction coordination", "")
Rel(distributed_transaction_engine, storage_layer_raft_consensus_rocksdb, "Reads and writes replicated data shards", "")
@enduml
